}

interface StatusFlags {
  threadId?: string;
  tail?: number;
  raw?: boolean;
  staleMinutes?: number;
}

interface ArchiveFlags {
  threadId?: string;
  completed?: boolean;
  yes?: boolean;
  dryRun?: boolean;
}

interface WaitFlags {
  threads?: string[];
  labels?: string[];
  all?: boolean;
  intervalMs?: number;
