        { id: 'msg-2', text: 'Second' },
        { id: 'msg-3', text: 'Third' },
      ]
        .map((entry) => JSON.stringify(entry))
        .join('\n') + '\n'
    );

    const { stdout, output } = captureOutput();
    await statusCommand({
      rootDir: codexRoot,
      threadId: 'thread-123',
      controllerId: 'controller-one',
      stdout,
      tail: 2,
      raw: true,
    });

