      rootDir: codexRoot,
      threadId: 'thread-123',
      controllerId: 'controller-one',
      stdout,
    });

    const text = output.join('');
    expect(text).toContain('Status: NOT RUNNING');
    expect(text).toContain('codex exec failed');
  });
});

import { describe, expect, it, vi, beforeEach } from 'vitest';
